import math
def priority(task, state, c=1.0, a=1.0, b=0.5, m=2.0):
    p = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    slack = task.due - state.now - p
    tier = m if task.tenant == 'premium' else 1.0
    if slack <= c * mean:
        return -task.due * tier + a * tier * task.weight / p * (1.0 + max(0.0, -slack) / mean)
    else:
        return -task.due + b * tier * task.weight / p

import math
def priority(task, state, c=1.0, k=1.5, b=0.25, m=1.75, a=0.5):
    p = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    slack = task.due - state.now - p
    wait = max(0.0, state.now - task.release)
    if slack <= c * mean:
        s = max(-50.0, min(50.0, slack / (k * mean)))
        urgency = math.exp(-s)
        return tier * task.weight / p * urgency + tier * task.weight * max(0.0, -slack) / (p + mean)
    else:
        wsp = tier * task.weight / p
        age = 1.0 + b * wait / (p + mean)
        duepull = math.exp(-max(0.0, slack) / (k * mean))
        return wsp * age * (a + duepull)

