import math
def priority(task, state, q_thresh=5.0, load_thresh=2.0, k=0.7, m=2.5, late_boost=1e3, w=0.1):
    est = max(task.estimated_runtime, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    slack = task.due - state.now - est
    tier = m if task.tenant == 'premium' else 1.0
    load = state.queue_work / max(state.capacity * mean_est, 1e-6)
    if slack <= 0.0:
        overdue = min(1000.0, max(0.0, -slack) / est)
        return tier * (1.0 + w * task.weight) / est + late_boost * task.weight * overdue
    if state.queue_len > q_thresh or load > load_thresh:
        return tier * task.weight / est * math.exp(-slack / max(k * mean_est, 1e-6))
    return tier * (1.0 + w * task.weight) / est + 1e-6 / max(slack, 1e-6)

