import math
def priority(task, state, k=0.5, c=1.0, beta=0.8, rho=0.25,
             floor=0.05, fit_bonus=0.2, queue_gain=0.5,
             load_gain=0.5, late_gain=0.3, premium_boost=0.0,
             map_m=1.0, reduce_m=1.0, join_m=1.0, other_m=1.0):
    p = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    cap = max(state.capacity, 1e-6)
    free = max(state.free, 0.0)
    need = max(task.resource_need, 1e-6)
    now = state.now

    load = max(0.0, state.queue_work) / max(cap * mean, 1e-6)
    scale = max(k * mean / (1.0 + load_gain * load), 1e-6)

    qwait = queue_gain * max(0.0, state.queue_work) / max(cap, 1e-6)
    if free > 0.0:
        rwait = mean * min(max(0.0, need - free) / max(free, 1e-6), c)
    else:
        rwait = mean * c

    slack = task.due - p - now - qwait - rwait
    z = (task.due - (now + p + qwait + rwait)) / scale

    if z > 50.0:
        sig = 0.0
    elif z < -50.0:
        sig = 1.0
    else:
        sig = 1.0 / max(1.0 + math.exp(z), 1e-6)

    risk = floor + (1.0 - floor) * sig
    base = task.weight / max(p ** beta, 1e-6) * risk

    if slack < 0.0:
        late = -slack
        base *= 1.0 + late_gain * late / max(late + c * mean, 1e-6)

    if slack > 0.0:
        laxness = slack / max(slack + c * mean, 1e-6)
        base /= max(1.0 + rho * laxness * need / cap, 1e-6)

    if need <= free:
        base *= 1.0 + fit_bonus
    else:
        base *= math.exp(-(need - free) / max(cap, 1e-6))

    if task.task_type == 'map':
        base *= map_m
    elif task.task_type == 'reduce':
        base *= reduce_m
    elif task.task_type == 'join':
        base *= join_m
    else:
        base *= other_m

    if task.tenant == 'premium':
        base *= 1.0 + premium_boost * risk

    return float(base)

